import{_ as e}from"./chunks/image-006.BzaDFqgA.js";import{_ as t,o as a,c as _,a3 as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/17-描述型论题和规定性论题.md","filePath":"books/xuehui-tiwen/17-描述型论题和规定性论题.md","lastUpdated":1794316978000}'),i={name:"books/xuehui-tiwen/17-描述型论题和规定性论题.md"};function o(r,p,n,l,c,d){return a(),_("div",null,[...p[0]||(p[0]=[s('<h2 id="描述型论题和规定性论题" tabindex="-1">描述型论题和规定性论题 <a class="header-anchor" href="#描述型论题和规定性论题" aria-label="Permalink to &quot;描述型论题和规定性论题&quot;">​</a></h2><p>此时此刻，识别出你通常遇到的两类论题将大有裨益。以下这些问题展示了其中的第一类论题：</p><p>音乐学习是不是有助于提高一个人的数学能力？</p><p>导致家庭暴力的最常见的诱因是什么？</p><p>服用帕罗西汀（Paxil）是不是治疗抑郁症的有效方法？</p><p>以上问题都有一个共同点：对它们的回答无一例外地都要描述某一事物过去、现在或将来客观是什么样的。比如说，前两个问题的答案有可能是“一般来说，受过音乐训练的孩子比没有受过音乐训练的孩子学起数学来更得心应手”以及“长期酗酒是引发家庭暴力最常见的诱因”。</p><p>这些论题都属于“描述性论题”（descriptive issues）。它们在图书、杂志、互联网、电视节目中较为常见，反映了我们对世间万物的存在方式及其秩序的好奇。请注意上述问题中的黑体部分：以这些方式提出的问题极有可能属于描述性论题。</p><p><img src="'+e+'" alt="" loading="lazy"></p><p>注意：描述性论题是指关于各种对过去、现在或将来的描述准确与否的问题。</p><p>现在，让我们来看看第二类论题的一些例子：</p><p>公立学校里应不应该教授智能设计？</p><p>对骗取医疗补助的行为应该采取什么措施？</p><p>我们应不应该禁止运动型多用途汽车的使用以缓解哮喘病发病率的上升势头？</p><p>上述问题都需要关于世间万物应该是什么样的答案。举例来说，前两个问题的答案可能是“公立学校里应该教授智能设计”以及“我们应该采取更严厉的惩罚措施来应对骗取医疗补助的行为”。</p><p>这些论题都属于伦理或道德范畴，它们提出的都是关于什么是对、什么是错、什么该有、什么不该有、什么是好、什么是坏的问题。它们需要的是规定性的答案。因此，我们将这些论题称为“规定性论题”（prescriptive issues）。社会论争通常都属于规定性论题。</p><p>这样说多少有点过度简化，有时候，我们很难判断所讨论的到底属于哪一类论题。不过，记住这两种不同的论题是很有用的，因为你最终做出的判断和评价的类型，将取决于你要回答的论题的类型。</p><p><img src="'+e+'" alt="" loading="lazy"></p><p>注意：规定性论题是指关于什么该做、什么不该做、什么是对、什么是错、什么是好、什么是坏的问题。</p>',18)])])}const h=t(i,[["render",o]]);export{f as __pageData,h as default};
